// deno-lint-ignore no-explicit-any
function createPhoneVerificationProvider(
  supabase: SupabaseClient<any, any, any>,
): PhoneVerificationProvider {
  const selected = (Deno.env.get("PHONE_VERIFICATION_PROVIDER") || "").toLowerCase();
  if (selected === "mock") {
    return new MockCaptureProvider(supabase);
  }
  // "twilio" | "vonage" | "whatsapp-cloud": entrega futura (ticket provider real).
  return new UnconfiguredProvider();
}

